from pathlib import Path
import json,hashlib,datetime
from PIL import Image
q=Path(__file__).parent;h=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();rows=[]
for folder in ['pack-native','ordinary']:
 for p in sorted((q/folder/'screenshots').glob('*.jpg')):
  im=Image.open(p);assert im.format=='JPEG';rows.append({'path':str(p.relative_to(q)),'sha256':h(p),'bytes':p.stat().st_size,'format':im.format,'size':list(im.size),'unedited_original':True})
assert len(rows)==26
log=(q/'pack-native/controlled.log').read_text();ordinary=(q/'ordinary/sidecar-runtime.log').read_text();assert (q/'pack-native/controlled.exit').read_text().strip()==(q/'ordinary/sidecar-runtime.exit').read_text().strip()=='0';assert all(x not in log+ordinary for x in ['ERROR:','instances leaked','resources still in use'])
data=[json.loads(l) for l in log.splitlines() if l.startswith('{')];steps=[d for d in data if 'controlled_runtime_step' in d];assert len(steps)==12
for c in range(1,5):
 ds=[d for d in steps if d['case']==c];assert [d['remaining'] for d in ds]==[2,1,0] and [d['coins'] for d in ds]==[73,74,75] and [d['xp'] for d in ds]==[1,2,3] and ds[-1]['floor_sources']==['medical']
helpers=[json.loads(l.split('TEST_AUDIO_TEARDOWN ',1)[1]) for l in log.splitlines() if l.startswith('TEST_AUDIO_TEARDOWN ')];assert len(helpers)==1;d=helpers[0];last=d['observations'][-1];assert d['complete'] and d['capture_removed'] and last['owners_released'] and last['streams_released'] and last['new_pushed']>=last['required_frames']>0 and last['silent_frames']>=last['required_frames'] and all(x['invalid']==x['discarded']==0 for x in d['observations'])
pins=json.loads((q/'FINAL_INPUTS.json').read_text());assert all(h(q/'project'/n)==s for n,s in pins.items());pack=q.parent/'moss-v36-pack/linux/MossCircuit.pck';assert h(pack)=='ea994144d3ae76926b29fad6467cb4bd36bfce73fcc96683694eb31c18caaba5'
(q/'NATIVE_CAPTURE_INDEX.json').write_text(json.dumps(rows,indent=2)+'\n')
